# An OAuth grant: a one-hour access token and the refresh token that renews
# it, on one row (generated by maquina:oauth). Only SHA-256 digests are
# stored; the raw values are returned once, in the response that issues them.
class AccessToken < ApplicationRecord
  ACCESS_TTL = 1.hour
  SCOPES = %w[read write].freeze

  class InvalidGrant < StandardError; end

  belongs_to :user
  belongs_to :oauth_client

  scope :unrevoked, -> { where(revoked_at: nil) }

  validate :scope_is_known

  def self.digest(raw)
    Digest::SHA256.hexdigest(raw.to_s)
  end

  # A space-separated scope string in SCOPES order, or nil when it names a
  # scope this server does not grant. A blank request means read.
  def self.normalize_scope(requested)
    scopes = requested.to_s.split
    return "read" if scopes.empty?

    scopes.uniq.sort_by { |scope| SCOPES.index(scope) || SCOPES.size }.join(" ") if (scopes - SCOPES).empty?
  end

  # [raw access token, raw refresh token], returned once.
  def self.issue!(user:, client:, scope:, resource:)
    access, refresh = SecureRandom.urlsafe_base64(32), SecureRandom.urlsafe_base64(32)
    create!(user: user, oauth_client: client, scope: scope, resource: resource, expires_at: ACCESS_TTL.from_now,
      token_digest: digest(access), refresh_token_digest: digest(refresh))
    [access, refresh]
  end

  # The live token for a raw access token: not revoked, not expired, and its
  # user not blocked. nil otherwise.
  def self.authenticate(raw)
    return if raw.blank?

    token = unrevoked.where("expires_at > ?", Time.current).find_by(token_digest: digest(raw))
    token unless token.nil? || token.user.blocked?
  end

  # The unrevoked row a raw refresh token belongs to, or nil.
  def self.find_by_refresh_token(raw)
    unrevoked.find_by(refresh_token_digest: digest(raw)) if raw.present?
  end

  # Spends this row's refresh token: revokes the row and returns a new
  # [raw access, raw refresh] pair with the same scope. Refresh tokens never
  # expire, but they are bound to the client they were issued to and work
  # once; anything else raises InvalidGrant.
  def rotate!(client:)
    raise InvalidGrant unless oauth_client == client && !user.blocked?

    transaction do
      raise InvalidGrant unless self.class.unrevoked.where(id: id).update_all(revoked_at: Time.current) == 1

      self.class.issue!(user: user, client: client, scope: scope, resource: resource)
    end
  end

  def revoke!
    update!(revoked_at: Time.current) unless revoked?
  end

  def revoked?
    revoked_at.present?
  end

  def scopes
    scope.to_s.split
  end

  private

  def scope_is_known
    errors.add(:scope, :inclusion) unless scopes.any? && (scopes - SCOPES).empty?
  end
end
